// bbx 假 @playwright/mcp：把启动参数、cwd 与几个环境变量记一行（mkdtemp 的 6 位随机后缀换成 <mkdtemp6>，只比位数），再按 MCP stdio 应答 initialize / tools/list（不起浏览器）。
import fs from 'node:fs';
import path from 'node:path';
const keep = {};
for (const k of ['HTTPS_PROXY', 'NO_PROXY', 'PILOTDECK_SESSION_BROWSER_PROXY']) if (k in process.env) keep[k] = process.env[k];
fs.appendFileSync('{PROJECT}/browser-launch.jsonl', JSON.stringify({ args: process.argv.slice(2).map((a) => a.replace(/(pilotdeck-mcp-browser-use-)[A-Za-z0-9]{6}$/, '$1<mkdtemp6>')), cwd: path.relative('{PROJECT}', process.cwd()), env: keep }) + '\n');
let buf = '';
process.stdin.on('data', (d) => {
  buf += d;
  let i;
  while ((i = buf.indexOf('\n')) >= 0) {
    const line = buf.slice(0, i); buf = buf.slice(i + 1);
    let msg; try { msg = JSON.parse(line); } catch { continue; }
    if (msg.id === undefined) continue;
    const result = msg.method === 'initialize'
      ? { protocolVersion: msg.params?.protocolVersion ?? '2025-06-18', capabilities: { tools: {} }, serverInfo: { name: 'bbx-fake-playwright', version: '0.0.0' } }
      : msg.method === 'tools/list' ? { tools: [] } : {};
    process.stdout.write(JSON.stringify({ jsonrpc: '2.0', id: msg.id, result }) + '\n');
  }
});
